/**
 * Color theme image catalog — 10 categories × 10 themes.
 *
 * Each theme is a flat 2D monochrome illustration (single core color on
 * white) generated by `scripts/generate-themes.mjs` and stored under
 * `public/themes/{category}/{id}-{portrait|landscape}.png`:
 *  - `-portrait.png` (1024×1536) = the applied full-screen theme
 *  - `-landscape.png` (1536×1024) = the thumbnail used in the picker
 *
 * The catalog mirrors the definitions in that script (category, name,
 * motif, color). The theme id is the unique key persisted in the
 * appearance store (`accent` = id when the user picked an image theme,
 * a preset key when they picked a plain accent color).
 */

export interface ThemeCatalogEntry {
  id: string;
  category: string;
  name: string;
  color: string;
  motif: string;
}

export interface ThemeCategory {
  id: string;
  name: string;
  themes: Omit<ThemeCatalogEntry, 'category'>[];
}

