/** All themes flattened (100 entries). */
export const ALL_THEMES: ThemeCatalogEntry[] = THEME_CATEGORIES.flatMap((c) =>
  c.themes.map((t) => ({ ...t, category: c.id })),
);

export function findThemeById(id: string | null | undefined): ThemeCatalogEntry | null {
  if (!id) return null;
  return ALL_THEMES.find((t) => t.id === id) ?? null;
}

/**
 * True when the given accent value (from the appearance store) points to an
 * image-based theme (as opposed to a plain color preset like 'magenta').
 */
export function isImageTheme(accent: string | null | undefined): boolean {
  return accent != null && findThemeById(accent) != null;
}

/** Image URLs for the catalog. */
export function themePortraitUrl(id: string): string {
  return `/themes/${id.split('-').slice(0, 2).join('-')}/${id}-portrait.png`;
}
export function themeLandscapeUrl(id: string): string {
  return `/themes/${id.split('-').slice(0, 2).join('-')}/${id}-landscape.png`;
}
